INSERT INTO inv_product (product_name, product_code, category_id, grade, sku, spec, size, unit, purchase_price, sales_price, sale_price_250g, sale_price_500g, cost_price, safety_stock_min, safety_stock_max, supplier_name, supplier_phone, supplier_remark, internal_tea_name, product_description, barcode, image_url, package_image_url, dry_tea_image_url, tea_soup_image_url, leaf_bottom_image_url, extra_image_url, shop_dept_id, status, del_flag, create_by, create_time, remark) VALUES
('清香铁观音', 'TGY0103001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '250g/罐', NULL, '斤', 26.50, 120.00, 60.00, 120.00, 84.00, 0.00, 0.00, '泉州安溪今世缘茶业有限公司', '13950190015', '含专票、含运费、含袋子', '001铁观音', '精选原产于福建泉州市安溪县西坪镇，铁观音茶介于绿茶和红茶之间，属于半发酵茶类，铁观音独具“观音韵”，清香雅韵，冲泡后有天然的兰花香，滋味纯浓,香气馥郁持久，有“七泡有余香之誉 ”。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 4'),
('武夷大红袍', 'DHP0103001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 61.00, 270.00, 135.00, 270.00, 189.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '大红袍', '武夷山核心产区，大红袍生长在武夷山的丹霞地貌中，茶条索紧结壮实，色泽乌润油亮；冲泡后汤色橙黄明亮，香气馥郁持久，带有兰花香；滋味醇厚回甘，岩韵显著。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 5'),
('武夷大红袍', 'DHP0103002', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 180.00, 800.00, 400.00, 800.00, 560.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '5号样大红袍', '外形条索紧结，色泽绿褐鲜润，冲泡后汤色橙黄明亮，叶片红绿相间。有兰花香，香高而持久，“岩韵”明显。大红袍生长在武夷山脉的茶叶独领山川灵气，山间岩缝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 6'),
('正岩大红袍', 'DHP0103003', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 450.00, 1980.00, 990.00, 1980.00, 1386.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '半岩大红袍', '武夷山核心产区，岩韵独特，与优异的自然环境是分不开的。外形条索紧结，色泽绿褐鲜润，汤色橙黄明亮，叶片红绿相间，品质最突出之处是香气馥郁有兰花香，香高而持久，明显。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 7'),
('武夷水仙', 'SX0103001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 160.00, 700.00, 350.00, 700.00, 490.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '水仙', '闽北高山水仙茶，又名武夷水仙茶，现主产区为建瓯、建阳两县。成茶条索紧结沉重，叶端扭曲，色泽油润暗沙绿，呈"蜻蜓头，青蛙腿"状;香气浓郁，具兰花清香，滋味醇厚回甘，汤色清澈橙黄，叶底厚软黄亮，叶缘朱砂红边或红点，即"三红七青"。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 8'),
('莲花峰老枞水仙', 'SX0103002', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 550.00, 2420.00, 1210.00, 2420.00, 1694.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '莲花峰老枞水仙', '产地武夷山莲花峰，独特的自然气候优势，使茶叶内含物质更丰富。外形条索紧结，色泽绿褐鲜润，冲泡后汤色橙黄明亮，叶片红绿相间。香气馥郁有兰花香，香高而持久，"岩韵"明显。很耐冲泡，冲泡七、八次仍有香味。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 9'),
('肉桂', 'RG0103001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 180.00, 800.00, 400.00, 800.00, 560.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '肉桂', '肉桂的桂皮香明显，香气久泡犹存；入口醇厚而鲜爽，汤色澄黄清澈，叶底黄亮，条索紧结卷曲，色泽褐绿，油润有光。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 10'),
('狮子峰肉桂', 'RG0103002', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '150g/罐', NULL, '斤', 550.00, 2420.00, 1210.00, 2420.00, 1694.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '狮子峰肉桂', '产于武夷山狮子峰，外形条索紧实，色泽乌润明亮，口感醇厚。由于当地独特的气候地理环境，形成了别具一格的岩韵品质特点，', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 11'),
('鸭屎香单丛', 'DC0103001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '乌龙茶' LIMIT 1), '一级', NULL, '125g/罐', NULL, '斤', 100.00, 450.00, 225.00, 450.00, 315.00, 0.00, 0.00, '潮州市乐源发茶厂', '18948499239', '含专票（别公司）、含运费，含袋子', '鸭屎香单丛', '凤凰单枞“鸭屎香”已是闻名遐迩，它属于乌龙茶类，其特点是，成茶索硕大紧沉重，色乌褐油润，汤色金黄，自然花香气浓郁，味道甘醇，韵味独特，回甘力强，极耐冲泡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 12'),
('正山小种(花果香型)', 'ZSXZ0102001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '一级', NULL, '250g/罐', NULL, '斤', 120.00, 520.00, 260.00, 520.00, 364.00, 0.00, 0.00, '武夷山市探春茶业有限公司', '13305096066', '含专票（别公司）、含运费、含袋子', '25果香正山小种1-2', '正山小种红茶的鼻祖，干茶壮实紧结，色泽乌黑油润，泡水后汤色红浓，香气高长带花果香浓厚，滋味醇爽，桂圆味水底香明显。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 13'),
('正山小种(甜香型)', 'ZSXZ0102002', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '一级', NULL, '250g/罐', NULL, '斤', 68.00, 300.00, 150.00, 300.00, 210.00, 0.00, 0.00, '武夷山市大齐茶业有限公司', '13305995232', '含专票、含运费、含袋子', '426-19正山小种', '外形条索肥实，色泽乌润，泡水后汤色红浓，香气高长带薯甜香，滋味醇厚，带有桂圆味。加入牛奶，茶香味不减，形成糖浆状奶茶，液色更为绚丽，备受青睐。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 14'),
('金骏眉(薯香型)', 'JJM0102001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '一级', NULL, '250g/罐', NULL, '斤', 80.00, 360.00, 180.00, 360.00, 252.00, 0.00, 0.00, '武夷山市探春茶业有限公司', '13305096066', '含专票（别公司）、含运费、含袋子', '金骏眉', '一年一采，且选用武夷山产区原料。外观上，干茶色泽独特均匀、金黄黑相间、乌中透黄、油润鲜活、有光泽、条索壮实紧结、夹杂着花果味，口感清甜顺滑。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 15'),
('金骏眉(花果香型)', 'JJM0102002', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '一级', NULL, '250g/罐', NULL, '斤', 230.00, 980.00, 490.00, 980.00, 686.00, 0.00, 0.00, '武夷山市探春茶业有限公司', '13305096066', NULL, '金骏眉', '原料选用当地的菜茶芽头，经过多重工序制成。它具有汤色金黄、汤中带甘、甘里透香的特点。干茶香气纯正，有花果香，香气清新优雅、细腻。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 16'),
('滇红工夫红茶', 'DH0102001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '一级', NULL, '125g/罐', NULL, '斤', 35.00, 160.00, 80.00, 160.00, 112.00, 0.00, 0.00, '云南龙泉茶业有限责任公司', '13759450887', '含专票、含运费、自行分装', '滇红', '云南滇红茶的品质优良，色泽红润透亮，汤色橙黄明亮。冲泡后的茶汤香气四溢，带有明显的果香、花香或蜜香，有时还能闻到一丝丝木香或草本香。入口时，滇红茶的滋味醇厚且甘甜，回甘持久。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 17'),
('祁门红茶', 'QH0102001', (SELECT category_id FROM inv_product_category WHERE shop_dept_id = 100 AND del_flag = '0' AND category_name = '红茶' LIMIT 1), '三级', NULL, '125g/罐', NULL, '斤', 32.00, 160.00, 80.00, 160.00, 112.00, 0.00, 0.00, '黄山毛峰茶业集团有限公司', '18855932128', '含专票、含运费、含袋子', '祁红三级', '安徽省黄山市祁门县一带。它以其独特的“祁门香”闻名于世，具有悠久的生产历史。传统祁门红茶外形紧细，色泽乌润，香气高雅，带有蜜糖香和花果香，汤色红艳明亮，滋味鲜爽甘醇，叶底嫩匀。在国际市场上被誉为“红茶皇后”', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, '0', '0', 'xlsx_import', NOW(), 'Excel row 18'),
